// M06-T06, the originals rule: every typed mechanism names its canonical
// original pinned by sha256 to the lineage.json canonical row, and its
// reference's expected/legacy.json (recorded by running the original) is
// regenerated by the port: every readout to the original's printed text,
// every outline, hole and score vertex within 1e-6 mm, the plan warnings,
// the logic and state sequences, and the reference build's bodies, whose
// outlines equal the legacy parts as the cut file packs them (Hausdorff
// within 1e-6 mm) and whose meshed volumes equal area x t within the
// D-175 snap grid's reach. A legacy value perturbed by one step fails.

import { readFileSync, readdirSync } from "node:fs";
import { describe, expect, test } from "vitest";
import { createProfileLookup, loadProfile } from "@hackbuild/profile";
import type { Ring, Vec2 } from "@hackbuild/spec";
import {
  mechanisms, sheetAudit, tumblerDefaults, tumblerModule, unflatten,
  type ModuleState, type SheetPart,
} from "@hackbuild/mechanisms";
import { ORIGINALS_OF_RECORD } from "../../../tools/test-support/originals-root.js";

interface LegacyPart { name: string; w: number; h: number; outer: number[][]; holes: number[][][]; score: number[][][] }
interface Legacy {
  mechanism: string; module: string;
  source: { lineage: string; sha256: string };
  material: { t: number; k: number; c: number; E: number };
  readouts: [string, string][]; warnings: string[][]; parts: LegacyPart[]; placed: [number, number][];
  logic?: { inputs: Record<string, number>; q: boolean }[]; levels?: number[]; sequence?: { inputs: Record<string, number>; q: number }[];
}
interface LineageRow { id: string; kind: string; source: string; sha256: string }

const root = new URL("../../../", import.meta.url);
const read = (p: string): string => readFileSync(new URL(p, root), "utf8");
const lineage = JSON.parse(read("lineage.json")) as LineageRow[];
const profile = createProfileLookup(loadProfile());
const TOL = 1e-6;
// TUMBLER entries regenerate through the module record below; a typed entry
// from another original holds its rule in its own test (balance-beam.body.test.ts).
const typed = mechanisms.entries.filter((e) => e.def.status === "typed" && e.def.original?.[0]?.slug === "tumbler");

const legacyOf = (ref: string): Legacy => JSON.parse(read(`reference/${ref}/expected/legacy.json`)) as Legacy;
const worst = (a: readonly (readonly number[])[], b: readonly (readonly number[])[]): number =>
  a.length !== b.length ? Infinity : a.reduce((m, p, i) => Math.max(m, Math.abs(p[0]! - b[i]![0]!), Math.abs(p[1]! - b[i]![1]!)), 0);

/** Every difference between the port's regeneration and a legacy record, as text. */
function regenerate(leg: Legacy): string[] {
  const mod = tumblerModule(leg.module)!;
  const flat = { ...tumblerDefaults(leg.module), t: leg.material.t, k: leg.material.k, c: leg.material.c, E: leg.material.E };
  const { p, m } = unflatten(mod, flat);
  const bad: string[] = [];
  const plan = mod.plan(p, m);
  if (plan.length !== leg.parts.length) bad.push(`${plan.length} parts, legacy ${leg.parts.length}`);
  plan.forEach((q: SheetPart, i) => {
    const l = leg.parts[i];
    if (l === undefined) return;
    if (q.name !== l.name) bad.push(`part ${i + 1} name ${q.name}`);
    if (worst(q.outer, l.outer) > TOL) bad.push(`${l.name} outer`);
    if (q.holes.length !== l.holes.length || q.holes.some((h, j) => worst(h, l.holes[j]!) > TOL)) bad.push(`${l.name} holes`);
    if (q.score.length !== l.score.length || q.score.some((s, j) => worst(s, l.score[j]!) > TOL)) bad.push(`${l.name} scores`);
  });
  if (JSON.stringify(plan.map((q) => sheetAudit(q, m.k))) !== JSON.stringify(leg.warnings)) bad.push("warnings");
  const zero: Record<string, number> = Object.fromEntries(mod.inputs.map((k) => [k, 0]));
  if (mod.id === "hinge") zero["A"] = 1;
  const read = mod.drive(p, m, zero, {}).read;
  if (JSON.stringify(read) !== JSON.stringify(leg.readouts)) bad.push(`readouts ${JSON.stringify(read)}`);
  for (const l of leg.logic ?? []) if ((mod.drive(p, m, l.inputs, {}).q > 0.5) !== l.q) bad.push(`logic ${JSON.stringify(l.inputs)}`);
  if (leg.levels !== undefined) {
    const lv = [0, 1, 2, 3, 4, 5, 6, 7].map((v) => mod.drive(p, m, { B0: v & 1, B1: (v >> 1) & 1, B2: (v >> 2) & 1 }, {}).q);
    if (JSON.stringify(lv) !== JSON.stringify(leg.levels)) bad.push("levels");
  }
  if (leg.sequence !== undefined) {
    const st: ModuleState = {};
    if (JSON.stringify(leg.sequence.map((s) => mod.drive(p, m, s.inputs, st).q)) !== JSON.stringify(leg.sequence.map((s) => s.q))) bad.push("sequence");
  }
  return bad;
}

/** The largest distance from a vertex of `ring` to the same vertex of `want`, either winding, or Infinity when the counts differ. */
function ringGap(ring: readonly Vec2[], want: readonly Vec2[]): number {
  if (ring.length !== want.length) return Infinity;
  const fwd = worst(ring, want);
  return Math.min(fwd, worst([...ring].reverse(), want));
}
/**
 * Area of the outer ring minus the union of the holes, by horizontal scan
 * lines at the midpoints of 0.005 mm bands: an independent measure of the
 * cut region that, unlike a sum of hole areas, counts overlapping holes
 * once and drops hole area outside the outline, as the original's cut does.
 */
function cutArea(outer: readonly (readonly number[])[], holes: readonly (readonly (readonly number[])[])[]): number {
  const dy = 0.005;
  const ys = outer.map((p) => p[1]!);
  const y0 = Math.min(...ys);
  const y1 = Math.max(...ys);
  const spans = (ring: readonly (readonly number[])[], y: number): [number, number][] => {
    const xs: number[] = [];
    for (let i = 0; i < ring.length; i++) {
      const a = ring[i]!;
      const b = ring[(i + 1) % ring.length]!;
      if ((a[1]! <= y) !== (b[1]! <= y)) xs.push(a[0]! + ((y - a[1]!) * (b[0]! - a[0]!)) / (b[1]! - a[1]!));
    }
    xs.sort((p, q) => p - q);
    const out: [number, number][] = [];
    for (let i = 0; i + 1 < xs.length; i += 2) out.push([xs[i]!, xs[i + 1]!]);
    return out;
  };
  let area = 0;
  for (let y = y0 + dy / 2; y < y1; y += dy) {
    const cut = holes.flatMap((h) => spans(h, y)).sort((p, q) => p[0] - q[0]);
    const merged: [number, number][] = [];
    for (const c of cut) {
      const last = merged[merged.length - 1];
      if (last !== undefined && c[0] <= last[1]) last[1] = Math.max(last[1], c[1]);
      else merged.push([c[0], c[1]]);
    }
    for (const [a, b] of spans(outer, y)) {
      let len = b - a;
      for (const [c, d] of merged) len -= Math.max(0, Math.min(b, d) - Math.max(a, c));
      area += len * dy;
    }
  }
  return area;
}

describe("the originals rule for every typed mechanism", () => {
  test("17 typed TUMBLER entries, each with a reference and a pinned canonical original", () => {
    expect(typed.length).toBe(17);
    for (const e of typed) {
      const o = e.def.original![0]!;
      const rows = lineage.filter((r) => r.source === `${ORIGINALS_OF_RECORD}${o.slug}/${o.file}`);
      expect(rows.some((r) => r.kind === "canonical" && r.sha256 === o.sha256), e.id).toBe(true);
      const leg = legacyOf(e.def.reference[0]!);
      expect(leg.mechanism, e.id).toBe(e.id);
      expect(leg.source.sha256, e.id).toBe(o.sha256);
      expect(lineage.find((r) => r.id === leg.source.lineage)?.kind, e.id).toBe("canonical");
    }
  });

  for (const e of typed) {
    test(`${e.id}: reference/${e.def.reference[0]} legacy numbers and parts regenerate`, () => {
      expect(regenerate(legacyOf(e.def.reference[0]!))).toEqual([]);
    });

    test(`${e.id}: the reference build's bodies are the legacy parts as the cut file packs them`, () => {
      const ref = e.def.reference[0]!;
      const leg = legacyOf(ref);
      const r = e.def.params["~standard"].validate({}) as { value: Readonly<Record<string, number>> };
      const out = e.def.apply!({ draft: { id: "", name: "", process: "laser", machine: "sheet600", frame: { originOnAxis: false, carriesOffset: false, pose: "print" }, bodies: [], features: [] }, face: { origin: [0, 0, 0], normal: [0, 0, 1], u: [1, 0, 0] }, params: r.value, profile });
      expect(out.bodies.length).toBe(leg.parts.length);
      const volumes = (JSON.parse(read(`reference/${ref}/expected/build.json`)) as { volumes: Record<string, number> }).volumes;
      out.bodies.forEach((b, i) => {
        const l = leg.parts[i]!;
        // Placements are the original's own packSheet run on its cut file width (record-tumbler.mjs).
        const [x, y] = leg.placed[i]!;
        const at = { x, y };
        const base = b.base as Extract<typeof b.base, { route: "prism" }>;
        const move = (pts: number[][]): Vec2[] => pts.map((q) => [q[0]! + at.x, q[1]! + at.y]);
        expect(ringGap(base.outline[0]! as Ring, move(l.outer)), `${l.name} outer`).toBeLessThan(TOL);
        l.holes.forEach((h, j) => expect(ringGap(base.outline[j + 1]! as Ring, move(h)), `${l.name} hole ${j + 1}`).toBeLessThan(TOL));
        expect(base.z).toEqual([0, leg.material.t]);
        // The meshed volume against the cut area x t: the prism route snaps every vertex to the
        // 1/1024 mm grid (D-175), so the bound is the outline length times half a grid step x t,
        // plus the scan's band error, one band height over the outline length x t.
        const want = cutArea(l.outer, l.holes) * leg.material.t;
        const perimeter = [l.outer, ...l.holes].reduce((a, ring) => a + ring.reduce((s, p, k) => { const q = ring[(k + 1) % ring.length]!; return s + Math.hypot(q[0]! - p[0]!, q[1]! - p[1]!); }, 0), 0);
        const got = volumes[`${e.id}.0.${b.id}`];
        expect(got, `${l.name} volume golden`).toBeDefined();
        expect(Math.abs(got! - want), `${l.name} volume`).toBeLessThanOrEqual(perimeter * (0.5 / 1024 + 0.005) * leg.material.t);
      });
    });
  }

  test("a perturbed legacy value fails: one readout digit, one vertex by 2e-6 mm", () => {
    const leg = legacyOf("joints/finger");
    expect(regenerate(leg)).toEqual([]);
    const text: Legacy = { ...leg, readouts: leg.readouts.map(([k, v], i) => [k, i === 1 ? v.replace("9.11", "9.12") : v]) };
    expect(regenerate(text).some((s) => s.startsWith("readouts"))).toBe(true);
    const vertex: Legacy = { ...leg, parts: leg.parts.map((p, i) => (i === 0 ? { ...p, outer: p.outer.map((q, j) => (j === 2 ? [q[0]! + 2e-6, q[1]!] : q)) } : p)) };
    expect(regenerate(vertex)).toContain(`${leg.parts[0]!.name} outer`);
  });

  test("no canon file or mechanism reference cites the quarantined mockups (D-222)", () => {
    const needle = ["fab-knowledge", "mockups"].join("/");
    const hits: string[] = [];
    const walk = (dir: URL): void => {
      for (const d of readdirSync(dir, { withFileTypes: true })) {
        if (d.name === "node_modules" || d.name === "dist") continue;
        const u = new URL(`${d.name}${d.isDirectory() ? "/" : ""}`, dir);
        if (d.isDirectory()) walk(u);
        else if (readFileSync(u, "utf8").includes(needle)) hits.push(u.pathname);
      }
    };
    for (const d of ["packages/mechanisms/", "reference/mechanisms/", "reference/joints/"]) walk(new URL(d, root));
    expect(hits).toEqual([]);
  });
});
